-- Supplemental P0 constraints and application-role permissions.
-- P0 baseline supplemental PostgreSQL constraints.
-- Prisma owns table creation from database/prisma/schema.prisma; this migration adds
-- the cross-table and permission constraints Prisma cannot express directly.

DO $$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'blackcat_app') THEN
    CREATE ROLE blackcat_app LOGIN PASSWORD 'blackcat_app';
  ELSE
    ALTER ROLE blackcat_app LOGIN PASSWORD 'blackcat_app';
  END IF;
END
$$;

GRANT USAGE ON SCHEMA public TO blackcat_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO blackcat_app;
GRANT USAGE, SELECT, UPDATE ON ALL SEQUENCES IN SCHEMA public TO blackcat_app;

-- Currency and non-negative money constraints. Every amount is stored as minor units.
ALTER TABLE orders
  ADD CONSTRAINT orders_currency_format_chk CHECK (currency ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT orders_amounts_non_negative_chk CHECK (
    amount_minor >= 0
    AND customer_unit_price_minor >= 0
    AND player_unit_payout_minor >= 0
    AND expected_player_earning_minor >= 0
  ),
  ADD CONSTRAINT order_active_customer_slot_status_chk CHECK (
    (status IN ('DRAFT', 'PENDING_DISPATCH', 'ACCEPTED', 'IN_SERVICE', 'PENDING_CONFIRMATION', 'EXCEPTION')
      AND active_customer_slot_id IS NOT NULL
      AND active_customer_slot_id = customer_id)
    OR (status IN ('COMPLETED', 'CANCELLED') AND active_customer_slot_id IS NULL)
  ),
  ADD CONSTRAINT order_active_player_slot_status_chk CHECK (
    (status IN ('ACCEPTED', 'IN_SERVICE', 'PENDING_CONFIRMATION') AND player_id IS NOT NULL
      AND active_player_slot_id IS NOT NULL
      AND active_player_slot_id = player_id)
    OR (status IN ('DRAFT', 'PENDING_DISPATCH', 'COMPLETED', 'CANCELLED') AND active_player_slot_id IS NULL)
    OR (status = 'EXCEPTION' AND (
      (player_id IS NULL AND active_player_slot_id IS NULL)
      OR (player_id IS NOT NULL AND active_player_slot_id IS NOT NULL AND active_player_slot_id = player_id)
    ))
  );

ALTER TABLE service_catalog_versions
  ADD CONSTRAINT service_catalog_currency_format_chk CHECK (currency ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT service_catalog_amounts_non_negative_chk CHECK (
    customer_unit_price_minor >= 0 AND player_unit_payout_minor >= 0 AND minimum_units > 0
  );

ALTER TABLE gift_catalog_versions
  ADD CONSTRAINT gift_catalog_currency_format_chk CHECK (currency ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT gift_catalog_amount_non_negative_chk CHECK (price_minor >= 0);

ALTER TABLE gift_requests
  ADD CONSTRAINT gift_requests_currency_format_chk CHECK (currency ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT gift_requests_amount_non_negative_chk CHECK (price_minor >= 0);

ALTER TABLE external_transactions
  ADD CONSTRAINT external_transactions_currency_format_chk CHECK (currency ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT external_transactions_amount_non_negative_chk CHECK (amount_minor >= 0);

ALTER TABLE refunds
  ADD CONSTRAINT refunds_currency_format_chk CHECK (currency ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT refunds_amount_non_negative_chk CHECK (amount_minor >= 0);

ALTER TABLE fund_reservations
  ADD CONSTRAINT fund_reservations_currency_format_chk CHECK (currency ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT fund_reservation_amounts_non_negative_chk CHECK (amount_minor >= 0),
  ADD CONSTRAINT fund_reservation_source_binding_chk CHECK (
    (source_type = 'ORDER' AND order_id IS NOT NULL AND gift_request_id IS NULL)
    OR (source_type = 'GIFT' AND gift_request_id IS NOT NULL AND order_id IS NULL)
  );

ALTER TABLE fund_reservation_events
  ADD CONSTRAINT fund_reservation_events_amount_non_negative_chk CHECK (amount_minor >= 0);

CREATE OR REPLACE FUNCTION enforce_fund_reservation_not_over_settled()
RETURNS trigger AS $$
DECLARE
  reservation_amount bigint;
  settled_amount bigint;
BEGIN
  SELECT amount_minor INTO reservation_amount
  FROM fund_reservations
  WHERE id = NEW.fund_reservation_id;

  SELECT COALESCE(SUM(amount_minor), 0) INTO settled_amount
  FROM fund_reservation_events
  WHERE fund_reservation_id = NEW.fund_reservation_id
    AND event_type IN ('CAPTURED', 'RELEASED', 'EXPIRED')
    AND id <> NEW.id;

  IF NEW.event_type IN ('CAPTURED', 'RELEASED', 'EXPIRED') THEN
    settled_amount := settled_amount + NEW.amount_minor;
  END IF;

  IF settled_amount > reservation_amount THEN
    RAISE EXCEPTION 'fund_reservation_not_over_settled_chk violated for reservation %', NEW.fund_reservation_id;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER fund_reservation_not_over_settled_chk
BEFORE INSERT OR UPDATE ON fund_reservation_events
FOR EACH ROW
EXECUTE FUNCTION enforce_fund_reservation_not_over_settled();

