CREATE OR REPLACE FUNCTION enforce_fund_reservation_event_guard()
RETURNS trigger AS $$
DECLARE
  reservation_record fund_reservations%ROWTYPE;
  last_sequence integer;
  settled_amount bigint;
BEGIN
  SELECT * INTO reservation_record
  FROM fund_reservations
  WHERE id = NEW.fund_reservation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'fund reservation % not found', NEW.fund_reservation_id;
  END IF;

  SELECT COALESCE(MAX(sequence), 0) INTO last_sequence
  FROM fund_reservation_events
  WHERE fund_reservation_id = NEW.fund_reservation_id;

  IF NEW.sequence <> last_sequence + 1 THEN
    RAISE EXCEPTION 'fund reservation event sequence must be %, got %', last_sequence + 1, NEW.sequence;
  END IF;

  IF last_sequence = 0 THEN
    IF NEW.event_type <> 'CREATED' OR NEW.amount_minor <> reservation_record.amount_minor OR NEW.reservation_version <> 1 THEN
      RAISE EXCEPTION 'first fund reservation event must be CREATED for full reservation amount at version 1';
    END IF;
    IF NEW.to_status NOT IN ('ACTIVE', 'PENDING', 'FAILED') THEN
      RAISE EXCEPTION 'first fund reservation event cannot transition to %', NEW.to_status;
    END IF;
  ELSE
    IF NEW.from_status IS DISTINCT FROM reservation_record.status THEN
      RAISE EXCEPTION 'fund reservation event from_status % does not match current status %', NEW.from_status, reservation_record.status;
    END IF;
    IF NEW.reservation_version <> reservation_record.row_version + 1 THEN
      RAISE EXCEPTION 'fund reservation event version must be %, got %', reservation_record.row_version + 1, NEW.reservation_version;
    END IF;
  END IF;

  IF last_sequence > 0 AND NOT (
    (reservation_record.status = 'PENDING' AND NEW.event_type IN ('ACTIVATED', 'FAILED') AND NEW.to_status IN ('ACTIVE', 'FAILED'))
    OR (reservation_record.status = 'ACTIVE' AND NEW.event_type IN ('CAPTURED', 'RELEASED', 'DISPUTED', 'EXPIRED') AND NEW.to_status IN ('PARTIALLY_SETTLED', 'CAPTURED', 'RELEASED', 'DISPUTED', 'EXPIRED'))
    OR (reservation_record.status = 'PARTIALLY_SETTLED' AND NEW.event_type IN ('CAPTURED', 'RELEASED', 'DISPUTED') AND NEW.to_status IN ('CAPTURED', 'RELEASED', 'DISPUTED'))
    OR (reservation_record.status = 'DISPUTED' AND NEW.event_type IN ('DISPUTE_RESOLVED', 'CAPTURED', 'RELEASED') AND NEW.to_status IN ('ACTIVE', 'PARTIALLY_SETTLED', 'CAPTURED', 'RELEASED'))
  ) THEN
    RAISE EXCEPTION 'invalid fund reservation transition from % via % to %', reservation_record.status, NEW.event_type, NEW.to_status;
  END IF;

  IF NEW.event_type IN ('DISPUTED', 'DISPUTE_RESOLVED', 'FAILED') AND NEW.amount_minor <> 0 THEN
    RAISE EXCEPTION 'non-settlement fund reservation events must have zero amount';
  END IF;

  SELECT COALESCE(SUM(amount_minor), 0) INTO settled_amount
  FROM fund_reservation_events
  WHERE fund_reservation_id = NEW.fund_reservation_id
    AND event_type IN ('CAPTURED', 'RELEASED', 'EXPIRED');

  IF NEW.event_type IN ('CAPTURED', 'RELEASED', 'EXPIRED') THEN
    settled_amount := settled_amount + NEW.amount_minor;
  END IF;

  IF settled_amount > reservation_record.amount_minor THEN
    RAISE EXCEPTION 'fund_reservation_not_over_settled_chk violated for reservation %', NEW.fund_reservation_id;
  END IF;

  IF NEW.to_status IN ('CAPTURED', 'RELEASED', 'EXPIRED')
    AND settled_amount <> reservation_record.amount_minor THEN
    RAISE EXCEPTION 'terminal fund reservation status % requires full settlement for reservation %', NEW.to_status, NEW.fund_reservation_id;
  END IF;

  UPDATE fund_reservations
  SET status = NEW.to_status,
      row_version = NEW.reservation_version,
      updated_at = now(),
      settled_at = CASE
        WHEN NEW.to_status IN ('CAPTURED', 'RELEASED', 'EXPIRED', 'FAILED') THEN COALESCE(settled_at, now())
        ELSE settled_at
      END
  WHERE id = NEW.fund_reservation_id;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_fund_reservation_event_guard
BEFORE INSERT ON fund_reservation_events
FOR EACH ROW
EXECUTE FUNCTION enforce_fund_reservation_event_guard();

CREATE OR REPLACE FUNCTION enforce_order_readiness_guard()
RETURNS trigger AS $$
BEGIN
  IF OLD.status = 'ACCEPTED' AND NEW.status = 'IN_SERVICE'
    AND COALESCE(current_setting('app.service_start_override', true), '') <> 'approved'
    AND (NEW.customer_ready_at IS NULL OR NEW.player_ready_at IS NULL) THEN
    RAISE EXCEPTION 'trg_order_readiness_guard requires both parties ready before service start';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_order_readiness_guard
BEFORE UPDATE ON orders
FOR EACH ROW
EXECUTE FUNCTION enforce_order_readiness_guard();

CREATE OR REPLACE FUNCTION enforce_order_service_started_event_guard()
RETURNS trigger AS $$
DECLARE
  required_event "OrderEventType";
BEGIN
  required_event := CASE
    WHEN COALESCE(current_setting('app.service_start_override', true), '') = 'approved'
      THEN 'SERVICE_STARTED_OVERRIDE'::"OrderEventType"
    ELSE 'SERVICE_STARTED'::"OrderEventType"
  END;

  IF OLD.status = 'ACCEPTED' AND NEW.status = 'IN_SERVICE'
    AND NOT EXISTS (
      SELECT 1
      FROM order_events
      WHERE order_id = NEW.id
        AND event_type = required_event
        AND from_status = 'ACCEPTED'
        AND to_status = 'IN_SERVICE'
    ) THEN
    RAISE EXCEPTION 'trg_order_readiness_guard requires matching % order event in the same transaction', required_event;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE CONSTRAINT TRIGGER trg_order_readiness_event_guard
AFTER UPDATE ON orders
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW
EXECUTE FUNCTION enforce_order_service_started_event_guard();

CREATE OR REPLACE FUNCTION enforce_referral_attribution_guard()
RETURNS trigger AS $$
DECLARE
  selected_program_type "ReferralProgramType";
  replaced_record referral_attributions%ROWTYPE;
BEGIN
  PERFORM 1 FROM users WHERE id = NEW.referred_user_id FOR UPDATE;

  SELECT program_type INTO selected_program_type
  FROM referral_program_versions
  WHERE id = NEW.program_version_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'referral program version % not found', NEW.program_version_id;
  END IF;

  IF NEW.status = 'FULFILLED' AND selected_program_type <> 'PROMOTER_FIRST_PURCHASE' THEN
    RAISE EXCEPTION 'FULFILLED referral attribution is only valid for PROMOTER_FIRST_PURCHASE';
  END IF;

  IF NEW.replaces_attribution_id IS NOT NULL THEN
    SELECT * INTO replaced_record
    FROM referral_attributions
    WHERE id = NEW.replaces_attribution_id;

    IF NOT FOUND OR replaced_record.referred_user_id <> NEW.referred_user_id OR replaced_record.status <> 'SUPERSEDED' THEN
      RAISE EXCEPTION 'replacement attribution must supersede an attribution for the same referred user';
    END IF;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_referral_attribution_guard
BEFORE INSERT OR UPDATE ON referral_attributions
FOR EACH ROW
EXECUTE FUNCTION enforce_referral_attribution_guard();

CREATE OR REPLACE FUNCTION enforce_commission_attribution_guard()
RETURNS trigger AS $$
DECLARE
  attribution_record referral_attributions%ROWTYPE;
  program_record referral_program_versions%ROWTYPE;
  consumption_record consumption_entries%ROWTYPE;
BEGIN
  SELECT * INTO attribution_record
  FROM referral_attributions
  WHERE id = NEW.referral_attribution_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'referral attribution % not found', NEW.referral_attribution_id;
  END IF;

  SELECT * INTO program_record
  FROM referral_program_versions
  WHERE id = attribution_record.program_version_id;

  SELECT * INTO consumption_record
  FROM consumption_entries
  WHERE id = NEW.source_consumption_entry_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'source consumption entry % not found', NEW.source_consumption_entry_id;
  END IF;

  IF NEW.beneficiary_user_id <> attribution_record.beneficiary_user_id
    OR NEW.program_type_snapshot <> program_record.program_type
    OR NEW.program_version_snapshot <> program_record.version
    OR NEW.award_mode_snapshot <> program_record.award_mode
    OR NEW.currency <> program_record.currency
    OR consumption_record.user_id <> attribution_record.referred_user_id
    OR consumption_record.direction <> 'DEBIT'
    OR (consumption_record.entry_type = 'ORDER_CHARGE' AND NOT program_record.eligible_order_spend)
    OR (consumption_record.entry_type = 'GIFT_CHARGE' AND NOT program_record.eligible_gift_spend)
    OR consumption_record.entry_type NOT IN ('ORDER_CHARGE', 'GIFT_CHARGE') THEN
    RAISE EXCEPTION 'commission attribution snapshot does not match source attribution, program, or consumption';
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_commission_attribution_guard
BEFORE INSERT OR UPDATE ON commissions
FOR EACH ROW
EXECUTE FUNCTION enforce_commission_attribution_guard();

CREATE OR REPLACE FUNCTION enforce_external_transaction_reservation_guard()
RETURNS trigger AS $$
DECLARE
  reservation_record fund_reservations%ROWTYPE;
BEGIN
  IF NEW.fund_reservation_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT * INTO reservation_record
  FROM fund_reservations
  WHERE id = NEW.fund_reservation_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'fund reservation % not found for external transaction', NEW.fund_reservation_id;
  END IF;

  IF NEW.user_id <> reservation_record.user_id
    OR NEW.currency <> reservation_record.currency
    OR NEW.amount_minor <> reservation_record.amount_minor
    OR COALESCE(NEW.order_id, '00000000-0000-0000-0000-000000000000'::uuid) IS DISTINCT FROM COALESCE(reservation_record.order_id, '00000000-0000-0000-0000-000000000000'::uuid)
    OR COALESCE(NEW.gift_request_id, '00000000-0000-0000-0000-000000000000'::uuid) IS DISTINCT FROM COALESCE(reservation_record.gift_request_id, '00000000-0000-0000-0000-000000000000'::uuid) THEN
    RAISE EXCEPTION 'external transaction does not mirror fund reservation source, user, amount, and currency';
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_external_transaction_reservation_guard
BEFORE INSERT OR UPDATE ON external_transactions
FOR EACH ROW
EXECUTE FUNCTION enforce_external_transaction_reservation_guard();

CREATE OR REPLACE FUNCTION enforce_guild_bot_config_event_immutable()
RETURNS trigger AS $$
DECLARE
  config_record guild_bot_configs%ROWTYPE;
BEGIN
  IF TG_OP IN ('UPDATE', 'DELETE') THEN
    RAISE EXCEPTION 'guild_bot_config_events are immutable';
  END IF;

  SELECT * INTO config_record
  FROM guild_bot_configs
  WHERE guild_id = NEW.guild_id
  FOR UPDATE;

  IF FOUND AND NEW.version <> config_record.version THEN
    RAISE EXCEPTION 'guild bot config event version % does not match current config version %', NEW.version, config_record.version;
  END IF;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_guild_bot_config_event_immutable
BEFORE INSERT OR UPDATE OR DELETE ON guild_bot_config_events
FOR EACH ROW
EXECUTE FUNCTION enforce_guild_bot_config_event_immutable();

-- Application role can append and perform status/version transitions through the API,
-- but cannot hard-delete immutable business facts or overwrite protected amounts.
REVOKE DELETE ON TABLE
  orders,
  order_events,
  order_resolutions,
  external_transactions,
  refunds,
  fund_reservations,
  fund_reservation_events,
  gift_requests,
  consumption_entries,
  player_earnings,
  player_earning_adjustments,
  commissions,
  commission_adjustments,
  audit_logs,
  guild_bot_config_events
FROM blackcat_app;

REVOKE DELETE ON TABLE audit_logs FROM blackcat_app;
REVOKE UPDATE, DELETE ON TABLE guild_bot_config_events FROM blackcat_app;
REVOKE UPDATE (amount_minor) ON fund_reservations FROM blackcat_app;
REVOKE UPDATE (customer_unit_price_minor, player_unit_payout_minor, amount_minor, expected_player_earning_minor) ON orders FROM blackcat_app;
REVOKE UPDATE (price_minor) ON gift_requests FROM blackcat_app;
REVOKE UPDATE (refund_amount_minor, player_earning_minor) ON order_resolutions FROM blackcat_app;
REVOKE UPDATE (amount_minor) ON fund_reservation_events FROM blackcat_app;
REVOKE UPDATE (amount_minor) ON external_transactions FROM blackcat_app;
REVOKE UPDATE (amount_minor) ON refunds FROM blackcat_app;
REVOKE UPDATE (amount_minor) ON consumption_entries FROM blackcat_app;
REVOKE UPDATE (unit_payout_minor, amount_minor) ON player_earnings FROM blackcat_app;
REVOKE UPDATE (amount_minor) ON player_earning_adjustments FROM blackcat_app;
REVOKE UPDATE (amount_minor) ON commissions FROM blackcat_app;
REVOKE UPDATE (amount_minor) ON commission_adjustments FROM blackcat_app;
